import 'package:flutter/material.dart';
import '../data/app_database.dart';
class ReportsPage extends StatefulWidget{const ReportsPage({super.key});@override State<ReportsPage> createState()=>_R();}
class _R extends State<ReportsPage>{Map<String,num> totals={};bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{totals=await AppDatabase.instance.dashboardTotals();if(mounted)setState(()=>loading=false);}Widget tile(String label,num value)=>Card(child:ListTile(title:Text(label),trailing:Text('$value',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))));@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Reports')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[tile('Sales invoices',totals['sales']??0),tile('Products',totals['products']??0),tile('Customers',totals['customers']??0),tile('Revenue',totals['revenue']??0),tile('Expenses',totals['expenses']??0),tile('Net',(totals['revenue']??0)-(totals['expenses']??0))])));}
